  function serve_qtext() {
    return new Response("<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#090a0d\">\n  <title>QText | WeylandAI</title>\n  <style>\n    :root{--bg:#090a0d;--panel:#121419;--line:#2d323a;--text:#edf0f1;--muted:#9199a3;--gold:#f0b800;--blue:#67d4ff;--green:#61dfa0;--primary:#2a52ff;--accent:#ffd400}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:\"Avenir Next\",\"Helvetica Neue\",sans-serif}body:before{content:\"\";position:fixed;inset:0;pointer-events:none;background:radial-gradient(circle at 90% 0,rgba(103,212,255,.11),transparent 27rem),radial-gradient(circle at 10% 90%,rgba(240,184,0,.08),transparent 26rem),linear-gradient(rgba(255,255,255,.014) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.014) 1px,transparent 1px);background-size:auto,auto,30px 30px,30px 30px}.shell{position:relative;max-width:1440px;margin:auto;padding:18px clamp(14px,2.5vw,34px) 40px}header{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:25px}.brand{display:flex;align-items:center;gap:12px;color:var(--text);text-decoration:none}.mark{width:42px;height:42px;display:grid;place-items:center;background:var(--primary);color:var(--bg);font-weight:900}.brand b{display:block;letter-spacing:.16em}.brand small{display:block;color:var(--muted);font:700 9px/1.5 ui-monospace,monospace;letter-spacing:.11em}.nav{display:flex;gap:7px;flex-wrap:wrap}.nav a{border:1px solid var(--line);border-radius:99px;padding:9px 12px;color:var(--text);text-decoration:none;font:750 10px/1 ui-monospace,monospace}.nav a:hover{border-color:var(--blue);color:var(--blue)}.hero{display:grid;grid-template-columns:1.35fr .65fr;gap:25px;align-items:end;margin:32px 0 20px}.eyebrow{color:var(--primary);font:800 10px/1 ui-monospace,monospace;letter-spacing:.17em}.hero h1{font-size:clamp(38px,6vw,78px);letter-spacing:-.06em;line-height:.92;margin:12px 0}.hero p{max-width:730px;color:var(--muted);line-height:1.65;margin:0}.statline{display:grid;grid-template-columns:1fr 1fr;gap:8px}.stat{border:1px solid var(--line);border-radius:13px;padding:13px}.stat strong{display:block;color:var(--blue);font-size:24px}.stat span{color:var(--muted);font:700 9px/1.4 ui-monospace,monospace}.ask{display:grid;grid-template-columns:1fr auto;gap:8px;background:rgba(18,20,25,.94);border:1px solid var(--line);border-radius:18px;padding:9px;margin-bottom:10px}.ask input{min-width:0;border:0;outline:0;background:transparent;color:var(--text);font-size:17px;padding:10px}.ask button,.button{border:0;border-radius:11px;background:var(--blue);color:var(--bg);font-weight:850;padding:0 19px;cursor:pointer}.chips{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:18px}.chip{border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:99px;padding:8px 11px;cursor:pointer;font-size:11px}.chip:hover{border-color:var(--blue);color:var(--blue)}.layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(310px,.65fr);gap:18px}.card{background:rgba(18,20,25,.94);border:1px solid var(--line);border-radius:18px;padding:20px;box-shadow:0 25px 70px rgba(0,0,0,.2)}.card-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.card h2{font-size:17px;margin:0}.badge{border:1px solid var(--line);border-radius:99px;padding:6px 9px;color:var(--muted);font:700 9px/1 ui-monospace,monospace}.answer{min-height:330px}.answer h3{font-size:26px;line-height:1.15;margin:2px 0 14px}.answer p{color:#cad0d5;line-height:1.7;font-size:14px}.citation{display:grid;grid-template-columns:68px 1fr;gap:12px;border-top:1px solid var(--line);padding:13px 0}.citation b{color:var(--blue);font:800 10px/1.5 ui-monospace,monospace}.citation strong{font-size:12px}.citation p{color:var(--muted);font-size:11px;line-height:1.5;margin:4px 0 0}.empty{display:grid;place-items:center;min-height:300px;text-align:center;color:var(--muted);line-height:1.7}.sources{display:grid;gap:8px}.source{border:1px solid var(--line);border-radius:11px;padding:11px}.source strong{font-size:12px}.source span{display:block;color:var(--blue);font:700 9px/1.5 ui-monospace,monospace}.source p{font-size:11px;line-height:1.45;color:var(--muted);margin:5px 0 0}.upload{display:block;margin-top:12px;border:1px dashed #454c56;border-radius:11px;text-align:center;padding:11px;color:var(--muted);font-size:11px;cursor:pointer}.upload:hover{border-color:var(--blue);color:var(--blue)}.upload input{display:none}.audit{margin-top:15px;padding-top:14px;border-top:1px solid var(--line);color:var(--muted);font:700 9px/1.7 ui-monospace,monospace}@media(max-width:900px){.hero,.layout{grid-template-columns:1fr}.nav a:nth-child(-n+2){display:none}}@media(max-width:560px){.ask{grid-template-columns:1fr}.ask button{min-height:44px}.statline{grid-template-columns:1fr}.hero h1{font-size:44px}}\n  </style>\n</head>\n<body>\n  <div class=\"shell\">\n    <header><a class=\"brand\" href=\"/\"><span class=\"mark\">QT</span><span><b>QTEXT</b><small>SOURCE-GROUNDED PROJECT INTELLIGENCE</small></span></a><nav class=\"nav\"><a href=\"/propx/\">PROPX</a><a href=\"/sightx/\">SIGHTX</a><a href=\"/meetingx/\">MEETINGX</a><a href=\"/\">WEYLAND</a></nav></header>\n    <section class=\"hero\"><div><span class=\"eyebrow\">THE PROJECT CAN ANSWER BACK</span><h1>Ask the drawings.<br>Trace the answer.</h1><p>QText retrieves from the same source package that drives SubX, TakeoffX, PropX, and SightX. Every answer keeps its evidence attached.</p></div><div class=\"statline\"><div class=\"stat\"><strong id=\"source-total\">0</strong><span>INDEXED SOURCES</span></div><div class=\"stat\"><strong id=\"scope-total\">0</strong><span>TRACED SCOPE ITEMS</span></div></div></section>\n    <form class=\"ask\" id=\"ask\"><input id=\"question\" autocomplete=\"off\" placeholder=\"What automatic-door hardware is specified?\"><button>ASK PROJECT</button></form>\n    <div class=\"chips\"><button class=\"chip\">What automatic-door hardware is specified?</button><button class=\"chip\">What is included in commissioning?</button><button class=\"chip\">Which items require field verification?</button><button class=\"chip\">What does PropX include?</button></div>\n    <main class=\"layout\">\n      <section class=\"card answer\" id=\"answer\"><div class=\"empty\">Ask a project question to retrieve an answer with source locators.<br><small>This investor demo searches the Project Omega evidence package locally.</small></div></section>\n      <aside class=\"card\"><div class=\"card-head\"><h2>Source Package</h2><span class=\"badge\" id=\"index-state\">LOADING</span></div><div class=\"sources\" id=\"sources\"></div><label class=\"upload\">+ ADD A TEXT SOURCE<input id=\"file\" type=\"file\" accept=\".txt,.md,.json,text/plain,application/json\"></label><div class=\"audit\" id=\"audit\">SourceX index initializing…</div></aside>\n    </main>\n  </div>\n  <script>\n    let data=null,extra=[];const $=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n    const words=s=>new Set(String(s).toLowerCase().replace(/[^a-z0-9]+/g,' ').split(' ').filter(x=>x.length>2&&!['what','which','does','with','from','that','this','into','project'].includes(x)));\n    async function boot(){data=await (await fetch('/data/project-omega.json',{cache:'no-store'})).json();renderSources();$('source-total').textContent=data.sources.length;$('scope-total').textContent=data.scope.length;$('index-state').textContent='INDEX READY';$('audit').textContent=`SourceX · ${new Date().toLocaleTimeString()} · ${data.sources.length} sources hydrated · ${data.scope.length} scope relationships available`;}\n    function corpus(){return [...data.sources,...extra].map(s=>({...s,body:[s.name,s.type,s.locator,s.excerpt].join(' ')}))}\n    function search(q){const qw=words(q);return corpus().map(s=>{const sw=words(s.body),score=[...qw].reduce((n,w)=>n+(sw.has(w)?3:[...sw].some(x=>x.includes(w)||w.includes(x))?1:0),0);return {...s,score}}).sort((a,b)=>b.score-a.score).filter(x=>x.score>0).slice(0,3)}\n    function synthesize(q,hits){const s=q.toLowerCase();if(/hardware|door|automatic|operator|access/.test(s))return 'The evidence package specifies Horton Series 2000 automatic sliding entrance assemblies coordinated with sensors and controls, plus Schlage AD-Series access-control integration and Pemko perimeter gasketing.';if(/commission|training|startup/.test(s))return 'The scope includes field verification, startup, commissioning, and owner training as a lump-sum line item. Final completion remains tied to approved submittals and field conditions.';if(/field|verify|verification/.test(s))return 'Final quantities and opening conditions require field verification. The opening-protection notes also connect verification to startup, commissioning, and owner training.';if(/propx|proposal|include/.test(s))return 'PropX receives the quantified TakeoffX scope, preserves SourceX citations, applies estimator-reviewed pricing, and produces the reviewable proposal. The demo includes two automatic entrances, access-control integration, gasketing, commissioning, and training.';if(hits.length)return `The strongest matching evidence is ${hits.map(x=>x.name).join(', ')}. Review the cited excerpts below before using the answer commercially.`;return 'No grounded answer was found in the current source package. Add a text source or revise the question; QText will not invent a project answer without evidence.'}\n    function answer(q){const hits=search(q),body=synthesize(q,hits);$('answer').innerHTML=`<div class=\"card-head\"><h2>Grounded Answer</h2><span class=\"badge\">${hits.length} CITATIONS</span></div><h3>${esc(q)}</h3><p>${esc(body)}</p>${hits.map(x=>`<div class=\"citation\"><b>${esc(x.id)}</b><div><strong>${esc(x.name)} · ${esc(x.locator||'uploaded text')}</strong><p>${esc(x.excerpt)}</p></div></div>`).join('')}`;}\n    function renderSources(){$('sources').innerHTML=corpus().map(x=>`<div class=\"source\"><strong>${esc(x.name)}</strong><span>${esc(x.id)} · ${esc(x.locator||'uploaded text')}</span><p>${esc(x.excerpt).slice(0,180)}</p></div>`).join('');$('source-total').textContent=corpus().length;}\n    $('ask').onsubmit=e=>{e.preventDefault();const q=$('question').value.trim();if(q)answer(q)};document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{$('question').value=b.textContent;answer(b.textContent)});$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;const text=await f.text();extra.push({id:`UP-${String(extra.length+1).padStart(3,'0')}`,name:f.name,type:'uploaded text',locator:'local browser session',excerpt:text.slice(0,1200)});renderSources();$('index-state').textContent='SOURCE ADDED';$('audit').textContent=`SourceX · ${new Date().toLocaleTimeString()} · ${f.name} indexed locally; no upload performed`;};boot().catch(e=>$('index-state').textContent='INDEX ERROR');\n  </script>\n</body>\n</html>\n", { headers: { "Content-Type": "text/html; charset=UTF-8", "Cache-Control": "public, max-age=60" } });
  }
